#include <bits/stdc++.h>
using namespace std;

bool check_f(const vector<int>& f, int p, int k) {
    for (int i = 0; i < p; ++i) {
        if (f[(k * i) % p] != (k * f[i]) % p) {
            return false;
        }
    }
    return true;
}

int generate_f(vector<int>& f, int p, int k, int index) {
    if (index == p) {
        return check_f(f, p, k) ? 1 : 0;
    }
    int total = 0;
    for (int val = 0; val < p; ++val) {
        f.push_back(val);
        total += generate_f(f, p, k, index + 1);
        f.pop_back();
    }
    return total;
}

int process(int p, int k) {
    long long total_count = 0;
    std::unordered_set<int> visited_indices;
    for (int start_idx = 0; start_idx < p; ++start_idx) {
        if (visited_indices.find(start_idx) == visited_indices.end()) {
            total_count++;
        }
        int current_idx = start_idx;
        while (visited_indices.find(current_idx) == visited_indices.end()) {
            visited_indices.insert(current_idx);
            current_idx = (current_idx * k) % p;
        }
    }
    const long long MOD = 1000000007;
    long long exponent = total_count - (k != 1 ? 1 : 0);
    long long result = 1;
    long long base = p % MOD;
    long long exp = exponent;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return static_cast<int>(result);
}

int main() {
    int p, k;
    std::cin >> p >> k;
    std::cout << process(p, k) << std::endl;
    return 0;
}
